// ── Navigation ─────────────────────────────────────────────────────────────
function showTab(id) {
  document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
  document.querySelectorAll('nav button').forEach(b => b.classList.remove('active'));
  document.getElementById('page-' + id).classList.add('active');
  event.target.classList.add('active');
  if (id === 'trends'    && !window._trendInit) initTrends();
  if (id === 'shopping'  && !window._slInit)    initShopping();
  if (id === 'positions' && !window._posInit)   initPositions();
  if (id === 'receipts'  && !window._recInit)   initReceipts();
  if (id === 'verbrauch' && !window._verbrauchInit) initVerbrauch();
  if (id === 'gruppen'   && !window._gruppenInit)   initGruppen();
  if (id === 'extras'    && !window._extrasInit) initExtras();
}

// ── PDF Export ──────────────────────────────────────────────────────────────
function openPdfModal() {
  document.getElementById('pdf-modal').classList.add('open');
}
function closePdfModal() {
  document.getElementById('pdf-modal').classList.remove('open');
}
function setPdfAll(checked) {
  document.querySelectorAll('.pdf-pg').forEach(c => c.checked = checked);
}
function doPdfExport() {
  const selected = Array.from(document.querySelectorAll('.pdf-pg:checked')).map(c => c.value);
  if (!selected.length) { alert('Bitte mindestens eine Seite auswählen.'); return; }
  closePdfModal();

  const lazyInit = {
    trends:   () => { if (!window._trendInit)    initTrends(); },
    shopping: () => { if (!window._slInit)        initShopping(); },
    positions:() => { if (!window._posInit)       initPositions(); },
    receipts: () => { if (!window._recInit)       initReceipts(); },
    verbrauch:() => { if (!window._verbrauchInit) initVerbrauch(); },
    gruppen:  () => { if (!window._gruppenInit)   initGruppen(); },
    extras:   () => { if (!window._extrasInit)    initExtras(); },
  };

  selected.forEach(id => {
    const page = document.getElementById('page-' + id);
    if (!page) return;
    page.classList.add('active');
    if (lazyInit[id]) lazyInit[id]();
    page.classList.remove('active');
    page.classList.add('print-visible');
  });

  document.body.classList.add('printing');

  window.addEventListener('afterprint', function cleanup() {
    document.querySelectorAll('.print-visible').forEach(p => p.classList.remove('print-visible'));
    document.body.classList.remove('printing');
    window.removeEventListener('afterprint', cleanup);
  });

  setTimeout(() => window.print(), 250);
}

// ── Universelle Tabellensortierung ──────────────────────────────────────────
function sortTable(th) {
  const table  = th.closest('table');
  const tbody  = table.querySelector('tbody');
  if (!tbody) return;
  const ths    = Array.from(th.closest('tr').querySelectorAll('th'));
  const col    = ths.indexOf(th);
  const wasAsc = th.dataset.dir === 'asc';
  const asc    = !wasAsc;

  ths.forEach(h => { delete h.dataset.dir; h.classList.remove('sort-asc','sort-desc'); });
  th.dataset.dir = asc ? 'asc' : 'desc';
  th.classList.add(asc ? 'sort-asc' : 'sort-desc');

  const rows = Array.from(tbody.querySelectorAll('tr'));
  rows.sort((a, b) => {
    const av = (a.cells[col]?.textContent || '').trim();
    const bv = (b.cells[col]?.textContent || '').trim();
    // Date DD.MM.YYYY
    if (/^\d{2}\.\d{2}\.\d{4}$/.test(av) && /^\d{2}\.\d{2}\.\d{4}$/.test(bv)) {
      const ad = av.split('.').reverse().join('');
      const bd = bv.split('.').reverse().join('');
      return asc ? ad.localeCompare(bd) : bd.localeCompare(ad);
    }
    // Numeric (strip €, %, +, spaces, swap decimal comma)
    const an = parseFloat(av.replace(/[€\s%+]/g,'').replace(/\./g,'').replace(',','.'));
    const bn = parseFloat(bv.replace(/[€\s%+]/g,'').replace(/\./g,'').replace(',','.'));
    if (!isNaN(an) && !isNaN(bn)) return asc ? an - bn : bn - an;
    // Text
    return asc ? av.localeCompare(bv,'de') : bv.localeCompare(av,'de');
  });
  rows.forEach(r => tbody.appendChild(r));
}

// ── Hilfsfunktionen ─────────────────────────────────────────────────────────

// Richtet th-Zellen rechtsbündig aus, wenn die zugehörige Datenspalte .num hat
function alignHeaders(table) {
  if (typeof table === 'string') table = document.getElementById(table);
  if (!table) return;
  const ths = Array.from(table.querySelectorAll('thead th'));
  const firstRow = table.querySelector('tbody tr');
  if (!firstRow) return;
  Array.from(firstRow.querySelectorAll('td')).forEach((td, i) => {
    if (td.classList.contains('num') && ths[i]) ths[i].classList.add('num');
  });
}

// Alle statischen Tabellen beim Laden ausrichten
document.addEventListener('DOMContentLoaded', () => {
  document.querySelectorAll('table').forEach(alignHeaders);
  renderForecast();
});

function eur(v) {
  if (v == null) return '–';
  return '€ ' + v.toLocaleString('de-DE', {minimumFractionDigits:2, maximumFractionDigits:2});
}
function isoDE(s) {
  if (!s) return '';
  const p = s.split('-');
  return p.length === 3 ? p[2] + '.' + p[1] + '.' + p[0] : s;
}

// ── Dashboard: Monats-Chart mit Jahres-Trennstrichen ───────────────────────
const yearSepPlugin = {
  id: 'yearSep',
  afterDraw(chart) {
    const {ctx, chartArea, scales} = chart;
    const labels = chart.data.labels;
    if (!labels || !scales.x) return;
    ctx.save();
    ctx.strokeStyle = '#88888866';
    ctx.lineWidth = 1.5;
    ctx.setLineDash([5, 4]);
    ctx.font = 'bold 11px sans-serif';
    ctx.fillStyle = '#999';
    ctx.textAlign = 'left';
    labels.forEach((label, i) => {
      if (i === 0) return;
      if (label.slice(0,4) !== labels[i-1].slice(0,4)) {
        // Mitte zwischen zwei Balken
        const xPrev = scales.x.getPixelForValue(i - 1);
        const xCurr = scales.x.getPixelForValue(i);
        const x = (xPrev + xCurr) / 2;
        ctx.beginPath();
        ctx.moveTo(x, chartArea.top);
        ctx.lineTo(x, chartArea.bottom);
        ctx.stroke();
        ctx.fillText(label.slice(0,4), x + 4, chartArea.top + 13);
      }
    });
    ctx.restore();
  }
};

