let _infMode = 'all';
function filterInflation(mode, btn) {
  _infMode = mode;
  document.querySelectorAll('.inf-active').forEach(b => b.classList.remove('inf-active'));
  btn.classList.add('inf-active');
  let data = INFLATION;
  if (mode === 'up')   data = INFLATION.filter(r => r.pct > 0);
  if (mode === 'down') data = INFLATION.filter(r => r.pct < 0).slice().reverse();
  renderInflation(data);
}

function renderInflation(data) {
  document.getElementById('inf-count').textContent = data.length + ' Artikel';
  document.getElementById('inf-body').innerHTML = data.map(r => {
    const cls = r.pct > 0 ? 'pct-pos' : 'pct-neg';
    const sign = r.pct > 0 ? '+' : '';
    return `<tr>
      <td>${r.n}</td>
      <td class="num">${r.fd}</td><td class="num">${eur(r.fp)}</td>
      <td class="num">${r.ld}</td><td class="num">${eur(r.lp)}</td>
      <td class="num"><span class="${cls}">${sign}${r.pct.toFixed(1).replace('.',',')} %</span></td>
      <td class="num">${r.cnt}</td>
    </tr>`;
  }).join('');
}

// ── Alle Positionen ─────────────────────────────────────────────────────────
let posItems = ALL_ITEMS.slice();
let posSort  = { key: 'd', dir: -1 };  // default: Datum absteigend

function initPositions() {
  window._posInit = true;
  applyPositions();
}

function sortPositions(th) {
  const key = th.dataset.key;
  if (posSort.key === key) posSort.dir *= -1;
  else posSort = { key, dir: 1 };
  document.querySelectorAll('#pos-table th').forEach(h => {
    h.classList.remove('sort-asc','sort-desc');
  });
  th.classList.add(posSort.dir === 1 ? 'sort-asc' : 'sort-desc');
  applyPositions();
}

function applyPositions() {
  const q   = (document.getElementById('pos-search')?.value || '').toLowerCase();
  const cat = document.getElementById('pos-cat')?.value || '';
  let items = ALL_ITEMS;
  if (q)   items = items.filter(r => r.n.toLowerCase().includes(q) || r.d.includes(q));
  if (cat) items = items.filter(r => r.cat === cat);

  const {key, dir} = posSort;
  items = [...items].sort((a, b) => {
    let av = a[key], bv = b[key];
    if (typeof av === 'string') av = av.toLowerCase();
    if (typeof bv === 'string') bv = bv.toLowerCase();
    return av < bv ? -dir : av > bv ? dir : 0;
  });

  const body = document.getElementById('pos-body');
  document.getElementById('items-count').textContent = items.length + ' Positionen';
  body.innerHTML = items.map(r => {
    const pdfPath = 'pdfs/' + r.src.replace('.eml', '.pdf');
    return `<tr>
      <td class="num">${isoDE(r.d)}</td>
      <td>${r.n}</td>
      <td>${catSelect(r.n, effCat(r.n,r.cat))}</td>
      <td class="num">${eur(r.p)}</td>
      <td class="num">${r.u > 0 ? (r.q < 1 ? eur(r.u)+' /kg' : eur(r.u)+' /Stk') : '–'}</td>
      <td class="num">${r.q > 1 ? r.q+'×' : r.q < 1 ? (r.q*1000).toFixed(0)+' g' : '–'}</td>
      <td><a href="${pdfPath}" target="_blank" class="pdf-link">📄</a></td>
    </tr>`;
  }).join('');
  alignHeaders('pos-table');
}

function filterPositions() { applyPositions(); }

// ── Kategorie-Override ───────────────────────────────────────────────────────
function effCat(name, cat) { return CAT_OVERRIDE[name] || cat; }

function catSelect(name, cur) {
  const safe = String(name).replace(/"/g, '&quot;');
  const opts = CATEGORY_NAMES.map(c =>
    '<option value="' + c + '"' + (c === cur ? ' selected' : '') + '>' + c + '</option>'
  ).join('');
  return '<select class="cat-badge-sel" data-name="' + safe + '" '
       + 'onclick="event.stopPropagation()" '
       + 'onchange="onCatChange(this)">' + opts + '</select>';
}

function onCatChange(sel) {
  const name = sel.dataset.name;
  const cat  = sel.value;
  CAT_OVERRIDE[name] = cat;
  fetch('save-categories.php', {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify(CAT_OVERRIDE)
  }).catch(() => {});
  applyPositions();
}

// ── Alle Belege ─────────────────────────────────────────────────────────────
let recSort = { key: 'date', dir: -1 };

function initReceipts() {
  window._recInit = true;
  applyReceipts();
}

function sortReceipts(th) {
  const key = th.dataset.key;
  if (recSort.key === key) recSort.dir *= -1;
  else recSort = { key, dir: 1 };
  document.querySelectorAll('#rec-table th').forEach(h =>
    h.classList.remove('sort-asc', 'sort-desc'));
  th.classList.add(recSort.dir === 1 ? 'sort-asc' : 'sort-desc');
  applyReceipts();
}

function applyReceipts() {
  const q = (document.getElementById('rec-search')?.value || '').toLowerCase();
  let list = ALL_RCPTS;
  if (q) list = list.filter(r =>
    r.date.includes(q) || r.bon.includes(q) || r.src.toLowerCase().includes(q));
  const {key, dir} = recSort;
  list = [...list].sort((a, b) => {
    let av = a[key] ?? '', bv = b[key] ?? '';
    if (typeof av === 'string') av = av.toLowerCase();
    if (typeof bv === 'string') bv = bv.toLowerCase();
    return av < bv ? -dir : av > bv ? dir : 0;
  });
  renderReceipts(list);
}

function renderReceipts(list) {
  const body = document.getElementById('rec-body');
  const rows = [];
  list.forEach((r, idx) => {
    rows.push(`<tr class="expandable-row" onclick="toggleReceipt(${idx}, this)" data-idx="${idx}">
      <td style="width:1.5rem;text-align:center;color:#cc0000">▶</td>
      <td class="num">${isoDE(r.date)}</td>
      <td class="num">${r.time}</td>
      <td class="num"><strong>${eur(r.total)}</strong></td>
      <td class="num"><span class="badge">${r.itemCnt}</span></td>
      <td class="num" style="color:#2a9d8f;font-size:.85rem">${r.bonus != null ? '+ ' + eur(r.bonus) : '–'}</td>
      <td><a href="${r.pdf}" target="_blank" onclick="event.stopPropagation()" class="pdf-link">📄 PDF</a></td>
    </tr>`);
  });
  body.innerHTML = rows.join('');
  body._list = list;
  alignHeaders('rec-table');
}

function toggleReceipt(idx, row) {
  // Remove existing expand row if open
  const next = row.nextElementSibling;
  if (next && next.classList.contains('expand-row')) {
    next.remove();
    row.cells[0].textContent = '▶';
    return;
  }
  // Close any other open expand rows
  document.querySelectorAll('.expand-row').forEach(r => r.remove());
  document.querySelectorAll('.expandable-row').forEach(r => { if(r.cells[0]) r.cells[0].textContent='▶'; });

  const r = document.getElementById('rec-body')._list[idx];
  const lines = r.lines || [];
  const itemRows = lines.map(l => {
    let einheit = '';
    if (l.q > 1)                          einheit = l.q + '× à ' + eur(l.u);
    else if (l.u && Math.abs(l.u - l.p) > 0.005) einheit = eur(l.u) + '/kg';
    return `<tr><td>${l.n}</td><td><span class="badge">${l.cat}</span></td>
      <td class="num">${eur(l.p)}</td>
      <td class="num" style="color:#888">${einheit}</td></tr>`;
  }).join('');

  const expand = document.createElement('tr');
  expand.className = 'expand-row';
  expand.innerHTML = `<td colspan="7">
    <table style="width:100%">
      <thead><tr>
        <th>Artikel</th><th>Kategorie</th>
        <th class="num">Preis</th><th class="num">Menge / Kilopreis</th>
      </tr></thead>
      <tbody>${itemRows}</tbody>
    </table>
  </td>`;
  row.after(expand);
  row.cells[0].textContent = '▼';
}

function filterReceipts() { applyReceipts(); }

// ── Gruppen ──────────────────────────────────────────────────────────────────
// Reverse map: alias -> canonical
const _GRPMAP = {};
for (const [canon, aliases] of Object.entries(GROUPS))
  for (const a of aliases) _GRPMAP[a] = canon;

// Alle eindeutigen Artikelnamen mit Kategorie (aus ALL_ITEMS)
const _ALL_NAMES = (() => {
  const seen = {};
  for (const r of ALL_ITEMS) if (!seen[r.n]) seen[r.n] = r.cat;
  return Object.entries(seen).sort((a,b) => a[0].localeCompare(b[0]));
})();

let _grpAssign = {};  // name -> canonical (working copy)

function _initGrpAssign() {
  _grpAssign = {};
  for (const [name] of _ALL_NAMES) {
    const g = _GRPMAP[name];
    if (g) _grpAssign[name] = g;
  }
}

function _updateRowStyle(input) {
  const isGrp = !!input.value.trim();
  const tr = input.closest('tr');
  tr.style.cssText = isGrp ? 'background:#fffdf0;border-left:3px solid #e9c46a' : '';
  input.style.cssText = isGrp
    ? 'width:100%;padding:.3rem .5rem;border:1px solid #e9c46a;border-radius:4px;font-size:.85rem;background:#fffdf0;font-weight:600'
    : 'width:100%;padding:.3rem .5rem;border:1px solid #ddd;border-radius:4px;font-size:.85rem';
}

function renderGruppen(names) {
  const body = document.getElementById('grp-body');
  body.innerHTML = names.map(([name, cat]) => {
    const val = _grpAssign[name] || '';
    const esc = name.replace(/"/g, '&quot;');
    const isGrp = !!val;
    const rowStyle = isGrp ? 'background:#fffdf0;border-left:3px solid #e9c46a' : '';
    const inputStyle = isGrp
      ? 'width:100%;padding:.3rem .5rem;border:1px solid #e9c46a;border-radius:4px;font-size:.85rem;background:#fffdf0;font-weight:600'
      : 'width:100%;padding:.3rem .5rem;border:1px solid #ddd;border-radius:4px;font-size:.85rem';
    return `<tr style="${rowStyle}">
      <td>${name}</td>
      <td><span class="badge">${cat}</span></td>
      <td><input type="text" value="${val}" data-name="${esc}"
           placeholder="Gruppenname…"
           oninput="_grpAssign[this.dataset.name]=this.value.trim(); updateGrpSummary(); _updateRowStyle(this);"
           style="${inputStyle}"></td>
    </tr>`;
  }).join('');
}

function filterGruppen() {
  const q = (document.getElementById('grp-search')?.value || '').toLowerCase();
  const names = q ? _ALL_NAMES.filter(([n]) => n.toLowerCase().includes(q)) : _ALL_NAMES;
  renderGruppen(names);
}

function updateGrpSummary() {
  const assigned = Object.values(_grpAssign).filter(v => v).length;
  const groups   = new Set(Object.values(_grpAssign).filter(v => v)).size;
  document.getElementById('grp-summary').textContent =
    assigned + ' Artikel in ' + groups + ' Gruppen';
}

function clearAllGroups() {
  _grpAssign = {};
  filterGruppen();
  updateGrpSummary();
}

function saveGroups() {
  const result = {};
  for (const [name, canon] of Object.entries(_grpAssign)) {
    if (!canon) continue;
    if (!result[canon]) result[canon] = [];
    result[canon].push(name);
  }
  const btn = document.getElementById('grp-save-btn');
  btn.disabled = true;
  btn.textContent = 'Speichern…';
  fetch('save-groups.php', {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify(result, null, 2),
  })
  .then(r => {
    if (!r.ok) throw new Error('HTTP ' + r.status);
    btn.textContent = '✓ Gespeichert';
    btn.style.background = '#2a9d8f';
    setTimeout(() => {
      btn.disabled = false;
      btn.textContent = 'Gruppen speichern';
      btn.style.background = '#cc0000';
    }, 2500);
  })
  .catch(() => {
    btn.disabled = false;
    btn.textContent = 'Gruppen speichern';
    alert('Server nicht erreichbar.\nBitte "Auswertung starten" über das Terminal ausführen.');
  });
}

let _pendingSuggestions = SUGGESTIONS.slice();

function _renderSuggestions() {
  const wrap = document.getElementById('grp-suggestions');
  const visible = _pendingSuggestions;
  document.getElementById('sugg-count').textContent =
    visible.length ? '(' + visible.length + ')' : '(keine offenen)';
  wrap.innerHTML = visible.map((s, i) => {
    const itemList = s.items.map((n, j) =>
      `<span style="background:#eee;border-radius:3px;padding:.1rem .3rem;font-size:.78rem;display:inline-flex;align-items:center;gap:.2rem">
        ${n}<button onclick="_removeSuggItem(${i},${j})" style="background:none;border:none;cursor:pointer;color:#999;font-size:.75rem;padding:0;line-height:1">✕</button>
      </span>`).join(' ');
    return `<div style="background:#fff;border:1px solid #e9c46a;border-radius:7px;padding:.55rem .75rem;min-width:220px;max-width:340px">
      <div style="font-weight:600;margin-bottom:.3rem;color:#333">
        ${s.canon}
        <span style="font-size:.75rem;color:#888;font-weight:400">(${s.total}×)</span>
      </div>
      <div style="margin-bottom:.5rem;display:flex;flex-wrap:wrap;gap:.2rem">${itemList}</div>
      <div style="display:flex;gap:.4rem">
        <button onclick="_acceptSuggestion(${i})"
          style="flex:1;background:#2a9d8f;color:#fff;border:none;border-radius:5px;padding:.3rem .5rem;cursor:pointer;font-size:.82rem">
          Übernehmen
        </button>
        <button onclick="_dismissSuggestion(${i})"
          style="background:#eee;border:none;border-radius:5px;padding:.3rem .5rem;cursor:pointer;font-size:.82rem">
          ✕
        </button>
      </div>
    </div>`;
  }).join('');
}

function _removeSuggItem(i, j) {
  _pendingSuggestions[i].items.splice(j, 1);
  if (_pendingSuggestions[i].items.length < 2) _pendingSuggestions.splice(i, 1);
  _renderSuggestions();
}

function _acceptSuggestion(i) {
  const s = _pendingSuggestions[i];
  s.items.forEach(name => { _grpAssign[name] = s.canon; });
  _pendingSuggestions.splice(i, 1);
  _renderSuggestions();
  updateGrpSummary();
  renderGruppen(_ALL_NAMES.filter(([n]) => {
    const q = (document.getElementById('grp-search')?.value || '').toLowerCase();
    return !q || n.toLowerCase().includes(q);
  }));
}

function _dismissSuggestion(i) {
  _pendingSuggestions.splice(i, 1);
  _renderSuggestions();
}

function initGruppen() {
  window._gruppenInit = true;
  _initGrpAssign();
  _renderSuggestions();
  renderGruppen(_ALL_NAMES);
  updateGrpSummary();
  alignHeaders('grp-table');
}

// ── Verbrauch ────────────────────────────────────────────────────────────────
let _roMode = 'all';
let _roSort = { key: 'days', dir: 1 };

function _reorderColor(days) {
  if (days < 0)  return '#cc0000';
  if (days <= 7) return '#e07b00';
  if (days <= 14) return '#c9a227';
  return '#2a9d8f';
}

function renderReorder(data) {
  document.getElementById('ro-count').textContent = data.length + ' Artikel';
  document.getElementById('ro-body').innerHTML = data.map(r => {
    const col = _reorderColor(r.days);
    const daysStr = r.days < 0
      ? `<span style="color:#cc0000;font-weight:600">${r.days} Tage</span>`
      : `<span style="color:${col};font-weight:600">+${r.days} Tage</span>`;
    const confDots = r.conf === 3
      ? '<span title="Hohe Konfidenz – regelmäßiger Rhythmus" style="color:#2a9d8f">●●●</span>'
      : r.conf === 2
      ? '<span title="Mittlere Konfidenz – leicht unregelmäßig" style="color:#e9c46a">●●<span style="color:#ddd">●</span></span>'
      : '<span title="Niedrige Konfidenz – unregelmäßige Kaufabstände" style="color:#e63946">●<span style="color:#ddd">●●</span></span>';
    const seasonBadge = r.seasonal
      ? ' <span style="font-size:.7rem;background:#e9c46a33;color:#b8860b;border-radius:3px;padding:.1rem .3rem" title="Saisonaler Artikel">Saisonal</span>'
      : '';
    return `<tr>
      <td>${r.n}${seasonBadge}</td>
      <td class="num">${isoDE(r.last)}</td>
      <td class="num">${r.interval} Tage</td>
      <td class="num">${isoDE(r.predicted)}</td>
      <td class="num">${daysStr}</td>
      <td class="num">${r.purchases}</td>
      <td class="num">${confDots}</td>
    </tr>`;
  }).join('');
}

function sortReorder(th) {
  const key = th.dataset.key;
  _roSort = _roSort.key === key ? {key, dir: _roSort.dir * -1} : {key, dir: 1};
  document.querySelectorAll('#ro-table th').forEach(h => h.classList.remove('sort-asc','sort-desc'));
  th.classList.add(_roSort.dir === 1 ? 'sort-asc' : 'sort-desc');
  filterReorder(_roMode, null);
}

function filterReorder(mode, btn) {
  _roMode = mode || _roMode;
  if (btn) {
    document.querySelectorAll('.ro-active').forEach(b => b.classList.remove('ro-active'));
    btn.classList.add('ro-active');
  }
  const q = (document.getElementById('ro-search')?.value || '').toLowerCase();
  let data = REORDER;
  if (_roMode === 'plausible') data = data.filter(r => r.plausible);
  if (_roMode === 'soon') data = data.filter(r => r.days >= 0 && r.days <= 14);
  if (_roMode === 'due')  data = data.filter(r => r.days < 0);
  if (q) data = data.filter(r => r.n.toLowerCase().includes(q));
  const {key, dir} = _roSort;
  data = data.slice().sort((a, b) => {
    let av = a[key], bv = b[key];
    if (typeof av === 'string') { av = av.toLowerCase(); bv = bv.toLowerCase(); }
    return av < bv ? -dir : av > bv ? dir : 0;
  });
  renderReorder(data);
}

let _kgSort = { key: 'kg_year', dir: -1 };
function _applyKg() {
  const q = (document.getElementById('kg-search')?.value || '').toLowerCase();
  let data = q ? CONSUMPTION_KG.filter(r => r.n.toLowerCase().includes(q)) : CONSUMPTION_KG.slice();
  const {key, dir} = _kgSort;
  data = data.slice().sort((a,b) => (a[key]<b[key]?-dir:a[key]>b[key]?dir:0));
  document.getElementById('kg-body').innerHTML = data.map(r =>
    `<tr><td>${r.n}<br><span class="badge">${r.cat}</span></td>
     <td class="num"><strong>${r.kg_year.toFixed(2).replace('.',',')} kg</strong></td>
     <td class="num" style="color:#888">${r.kg_total.toFixed(2).replace('.',',')} kg</td></tr>`
  ).join('');
}
function filterKg() { _applyKg(); }
function sortKg(th) {
  const key = th.dataset.key;
  _kgSort = _kgSort.key===key ? {key,dir:_kgSort.dir*-1} : {key,dir:-1};
  document.querySelectorAll('#kg-table th').forEach(h=>h.classList.remove('sort-asc','sort-desc'));
  th.classList.add(_kgSort.dir===1?'sort-asc':'sort-desc');
  _applyKg();
}

let _stkSort = { key: 'stk_year', dir: -1 };
function _applyStk() {
  const q = (document.getElementById('stk-search')?.value || '').toLowerCase();
  let data = q ? CONSUMPTION_STK.filter(r => r.n.toLowerCase().includes(q)) : CONSUMPTION_STK.slice();
  const {key, dir} = _stkSort;
  data = data.slice().sort((a,b) => (a[key]<b[key]?-dir:a[key]>b[key]?dir:0));
  const _stkGrpNames = new Set(Object.keys(GROUPS));
  const rows = data.map(r => {
    const isGrp = _stkGrpNames.has(r.n) && STK_DETAIL[r.n];
    const hasGrpStyle = _stkGrpNames.has(r.n);
    const grpMark = hasGrpStyle ? ' <span style="font-size:.7rem;background:#e9c46a33;color:#b8860b;border-radius:3px;padding:.1rem .3rem;vertical-align:middle">Gruppe</span>' : '';
    const rowBg = hasGrpStyle ? 'background:#fffdf0' : '';
    const daysStr = r.days_per != null ? r.days_per.toFixed(1).replace('.',',') + ' Tage' : '–';
    const tog = isGrp ? '<span class="stk-toggle" style="float:left;margin-left:-1.4rem;width:1.2rem;color:#cc0000;text-align:center">▶</span>' : '';
    const dataGrp = isGrp ? ' data-grp="' + r.n.replace(/"/g,'') + '"' : '';
    const cursor = isGrp ? 'cursor:pointer' : '';
    return '<tr class="' + (isGrp ? 'stk-grp-row' : '') + '" style="' + rowBg + ';' + cursor + '"' + dataGrp + '>'
      + '<td style="padding-left:1.4rem">' + tog + r.n + grpMark + '<br><span class="badge" style="display:inline-block;margin-top:3px">' + r.cat + '</span></td>'
      + '<td class="num"><strong>' + r.stk_year.toFixed(1).replace('.',',') + ' Stk</strong></td>'
      + '<td class="num" style="color:#457b9d">' + daysStr + '</td>'
      + '<td class="num" style="color:#888">' + r.stk_total + ' Stk</td></tr>';
  });
  document.getElementById('stk-body').innerHTML = rows.join('');
  document.querySelectorAll('#stk-body .stk-grp-row').forEach(row => {
    row.addEventListener('click', () => toggleStkGroup(row.dataset.grp, row));
  });
}
function filterStk() { _applyStk(); }
function sortStk(th) {
  const key = th.dataset.key;
  _stkSort = _stkSort.key===key ? {key,dir:_stkSort.dir*-1} : {key,dir:-1};
  document.querySelectorAll('#stk-table th').forEach(h=>h.classList.remove('sort-asc','sort-desc'));
  th.classList.add(_stkSort.dir===1?'sort-asc':'sort-desc');
  _applyStk();
}

function toggleStkGroup(name, row) {
  const next = row.nextElementSibling;
  const toggle = row.querySelector('.stk-toggle');
  if (next && next.classList.contains('stk-expand-row')) {
    next.remove();
    if (toggle) toggle.textContent = '▶';
    return;
  }
  document.querySelectorAll('.stk-expand-row').forEach(r => r.remove());
  document.querySelectorAll('.stk-toggle').forEach(t => t.textContent = '▶');
  const items = STK_DETAIL[name] || [];
  const itemRows = items.map(i => {
    const d = i.days_per != null ? i.days_per.toFixed(1).replace('.',',') + ' Tage' : '–';
    return '<tr>'
      + '<td style="padding-left:1.5rem">' + i.n + '</td>'
      + '<td class="num">' + i.stk_year.toFixed(1).replace('.',',') + ' Stk/Jahr</td>'
      + '<td class="num" style="color:#457b9d">' + d + '</td>'
      + '<td class="num" style="color:#888">' + i.stk_total + ' Stk</td>'
      + '</tr>';
  }).join('');
  const expand = document.createElement('tr');
  expand.className = 'stk-expand-row';
  const cell = document.createElement('td');
  cell.colSpan = 4;
  cell.style.padding = '0';
  cell.innerHTML = '<table style="width:100%;font-size:.85rem"><tbody>' + itemRows + '</tbody></table>';
  expand.appendChild(cell);
  row.after(expand);
  if (toggle) toggle.textContent = '▼';
}
let _lifeSort = { key: 'days_per', dir: 1 };
function renderLifespan() {
  const q = (document.getElementById('life-search')?.value || '').toLowerCase();
  let data = q ? CONSUMPTION_LIFESPAN.filter(r => r.n.toLowerCase().includes(q))
                : CONSUMPTION_LIFESPAN.slice();
  const {key, dir} = _lifeSort;
  data.sort((a,b) => {
    const av = a[key], bv = b[key];
    if (av == null && bv == null) return 0;
    if (av == null) return 1;
    if (bv == null) return -1;
    return av < bv ? -dir : av > bv ? dir : 0;
  });
  const _lifeGrpNames = new Set(Object.keys(GROUPS));
  document.getElementById('life-body').innerHTML = data.map(r => {
    const isGrp = _lifeGrpNames.has(r.n) && LIFESPAN_DETAIL[r.n];
    const tog = isGrp ? '<span class="life-toggle" style="float:left;margin-left:-1.4rem;width:1.2rem;color:#cc0000;text-align:center">▶</span>' : '';
    const grpMark = isGrp ? ' <span style="font-size:.7rem;background:#e9c46a33;color:#b8860b;border-radius:3px;padding:.1rem .3rem;vertical-align:middle">Gruppe</span>' : '';
    const rowBg = isGrp ? 'background:#fffdf0' : '';
    const cursor = isGrp ? 'cursor:pointer' : '';
    const dataGrp = isGrp ? ' data-grp="' + r.n.replace(/"/g,'') + '"' : '';
    const daysStr = r.days_per != null ? r.days_per.toFixed(1).replace('.',',') + ' Tage' : '–';
    const pwStr = r.per_week != null ? r.per_week.toFixed(2).replace('.',',') + ' ' + r.unit : '–';
    const totStr = r.unit === 'kg'
      ? r.amount.toFixed(2).replace('.',',') + ' kg'
      : Math.round(r.amount) + ' Stk';
    return '<tr style="' + rowBg + ';' + cursor + '"' + dataGrp + '>'
      + '<td style="padding-left:1.4rem">' + tog + r.n + grpMark + '<br><span class="badge" style="display:inline-block;margin-top:3px">' + r.cat + '</span></td>'
      + '<td>1 ' + r.unit + '</td>'
      + '<td class="num" style="color:#457b9d;font-weight:600">' + daysStr + '</td>'
      + '<td class="num"><strong>' + pwStr + '</strong></td>'
      + '<td class="num">' + r.buys + '×</td>'
      + '<td class="num" style="color:#888">' + totStr + '</td>'
      + '</tr>';
  }).join('');
  document.querySelectorAll('#life-body tr[data-grp]').forEach(row => {
    row.addEventListener('click', () => toggleLifespanGroup(row.dataset.grp, row));
  });
  const cnt = document.getElementById('life-count');
  if (cnt) cnt.textContent = data.length + ' Artikel';
}
function toggleLifespanGroup(grp, row) {
  const existing = row.nextElementSibling;
  if (existing && existing.classList.contains('life-expand-row')) {
    existing.remove();
    row.querySelectorAll('.life-toggle').forEach(t => t.textContent = '▶');
    return;
  }
  document.querySelectorAll('.life-expand-row').forEach(r => r.remove());
  document.querySelectorAll('.life-toggle').forEach(t => t.textContent = '▶');
  const items = LIFESPAN_DETAIL[grp] || [];
  const itemRows = items.map(d => {
    const ds = d.days_per != null ? d.days_per.toFixed(1).replace('.',',') + ' Tage' : '–';
    const pw = d.per_week != null ? d.per_week.toFixed(2).replace('.',',') + ' ' + d.unit : '–';
    const tot = d.unit === 'kg' ? d.amount.toFixed(2).replace('.',',') + ' kg' : Math.round(d.amount) + ' Stk';
    return '<tr><td style="padding-left:.5rem;color:#555">' + d.n + '</td>'
      + '<td>1 ' + d.unit + '</td>'
      + '<td class="num" style="color:#457b9d">' + ds + '</td>'
      + '<td class="num">' + pw + '</td>'
      + '<td class="num"></td>'
      + '<td class="num" style="color:#888">' + tot + '</td></tr>';
  }).join('');
  const expand = document.createElement('tr');
  expand.className = 'life-expand-row';
  const cell = document.createElement('td');
  cell.colSpan = 6;
  cell.style.padding = '0';
  cell.innerHTML = '<table style="width:100%;font-size:.85rem"><tbody>' + itemRows + '</tbody></table>';
  expand.appendChild(cell);
  row.after(expand);
  const toggle = row.querySelector('.life-toggle');
  if (toggle) toggle.textContent = '▼';
}
function sortLifespan(th) {
  const key = th.dataset.key;
  _lifeSort = _lifeSort.key===key ? {key,dir:_lifeSort.dir*-1} : {key,dir:-1};
  document.querySelectorAll('#life-table th').forEach(h=>h.classList.remove('sort-asc','sort-desc'));
  th.classList.add(_lifeSort.dir===1?'sort-asc':'sort-desc');
  renderLifespan();
}

function initVerbrauch() {
  window._verbrauchInit = true;
  filterReorder('plausible', document.querySelector('.ro-active'));
  _applyKg();
  _applyStk();
  renderLifespan();
  alignHeaders('ro-table');
  alignHeaders('kg-table');
  alignHeaders('stk-table');
  alignHeaders('life-table');
}

// ── Einkaufszettel ───────────────────────────────────────────────────────────
const _SL_ICONS = {
  'Obst':'🍎','Gemüse':'🥦','Fleisch & Wurst':'🥩','Fisch & Meeresfrüchte':'🐟',
  'Milch & Käse & Eier':'🥛','Backwaren':'🥖','Getränke':'🥤','Tiefkühl':'🧊',
  'Süßes & Snacks':'🍪','Grundnahrungsmittel':'🌾','Fertiggerichte & Konserven':'🥫',
  'Körperpflege':'🧴','Haushalt':'🧽','Pfand':'♻️','Sonstiges':'📦'
};

let _slActive = {};   // names der aktiv gewählten Artikel (Auto-Vorschläge, die der User akzeptiert hat)
let _slCustom = [];     // eigene Einträge (sind immer aktiv, bis manuell entfernt)

(function _slLoadState() {
  try { _slActive = JSON.parse(localStorage.getItem('rewe_sl_active') || '{}'); } catch(e) {}
  try { _slCustom = JSON.parse(localStorage.getItem('rewe_sl_custom') || '[]'); } catch(e) {}
})();

function _slSave() {
  try {
    localStorage.setItem('rewe_sl_active', JSON.stringify(_slActive));
    localStorage.setItem('rewe_sl_custom', JSON.stringify(_slCustom));
  } catch(e) {}
}

function _slLookupCat(name) {
  for (const r of ALL_ITEMS) if (r.n === name) return effCat(r.n, r.cat);
  return 'Sonstiges';
}

function initShopping() {
  window._slInit = true;
  renderShoppingList();
}

function _slEnrich(r, lifeMap) {
  const life = lifeMap[r.n];
  let qty = '', unit = '';
  if (life && life.per_week) {
    const weeks = Math.max(r.interval / 7, 1);
    const amount = life.per_week * weeks;
    if (life.unit === 'kg') {
      qty = amount.toFixed(2).replace('.', ',');
      unit = 'kg';
    } else {
      qty = Math.max(1, Math.round(amount)).toString();
      unit = 'Stk';
    }
  }
  return { n: r.n, days: r.days, interval: r.interval, conf: r.conf,
           qty, unit, custom: false, cat: _slLookupCat(r.n) };
}

function renderShoppingList() {
  const horizon = parseInt(document.getElementById('sl-horizon')?.value || '7', 10);
  const lifeMap = {};
  CONSUMPTION_LIFESPAN.forEach(r => lifeMap[r.n] = r);

  const reorderMap = {};
  REORDER.forEach(r => reorderMap[r.n] = r);

  // Aktive Liste: vom User gewählte Auto-Vorschläge + alle Custom-Einträge
  const activeAuto = Object.keys(_slActive)
    .filter(n => reorderMap[n])
    .map(n => _slEnrich(reorderMap[n], lifeMap));
  const activeCustom = _slCustom.map(n => ({
    n, days: null, qty: '', unit: '', custom: true, cat: _slLookupCat(n)
  }));
  const active = activeCustom.concat(activeAuto)
    .sort((a, b) => {
      if (a.custom !== b.custom) return a.custom ? -1 : 1;  // Custom oben
      return (a.days ?? 999) - (b.days ?? 999);
    });

  // Vorschläge: nur Artikel mit messbarem Verbrauch (CONSUMPTION_LIFESPAN),
  // mit REORDER-Datum gejoint. Pfand ausgeschlossen.
  const suggestions = CONSUMPTION_LIFESPAN
    .filter(life => life.cat !== 'Pfand')
    .map(life => {
      const r = reorderMap[life.n];
      if (!r || !r.plausible || r.seasonal) return null;
      if (r.days > horizon) return null;
      if (r.days < -Math.max(r.interval, 7)) return null;
      if (_slActive[life.n]) return null;
      // Empfohlene Menge aus Wochenverbrauch × Intervall
      const weeks  = Math.max(r.interval / 7, 1);
      const amount = life.per_week * weeks;
      let qty = '', unit = '';
      if (life.unit === 'kg') {
        qty = amount.toFixed(2).replace('.', ','); unit = 'kg';
      } else {
        qty = Math.max(1, Math.round(amount)).toString(); unit = 'Stk';
      }
      return { n: life.n, days: r.days, interval: r.interval, qty, unit,
               custom: false, cat: life.cat };
    })
    .filter(it => it !== null)
    .sort((a, b) => {
      // Relative Position im Kaufzyklus: -1 = 1 Zyklus überfällig, 0 = heute
      const ar = a.interval > 0 ? a.days / a.interval : a.days;
      const br = b.interval > 0 ? b.days / b.interval : b.days;
      return ar - br;
    });

  document.getElementById('sl-active').innerHTML = active.length
    ? active.map(_slCardHtml).join('')
    : '<div class="sl-empty">Liste leer – wähle aus den Vorschlägen unten oder tippe etwas ein</div>';

  document.getElementById('sl-recent').innerHTML = suggestions.length
    ? suggestions.map(_slCardHtml).join('')
    : '<div class="sl-empty" style="opacity:.6">Keine Vorschläge in diesem Zeitraum</div>';

  document.getElementById('sl-recent-count').textContent =
    suggestions.length ? suggestions.length + ' Vorschläge' : '';

  document.querySelectorAll('#sl-active .sl-card').forEach(c => {
    c.addEventListener('click', () => _slRemoveFromActive(c.dataset.name));
  });
  document.querySelectorAll('#sl-recent .sl-card').forEach(c => {
    c.addEventListener('click', () => _slAddToActive(c.dataset.name));
  });
}

function _slAddToActive(name) {
  _slActive[name] = true;
  _slSave();
  renderShoppingList();
}

function _slRemoveFromActive(name) {
  delete _slActive[name];
  const idx = _slCustom.indexOf(name);
  if (idx >= 0) _slCustom.splice(idx, 1);
  _slSave();
  renderShoppingList();
}

function clearActiveList() {
  if (!Object.keys(_slActive).length && !_slCustom.length) return;
  if (confirm('Aktive Einkaufsliste leeren?')) {
    _slActive = {};
    _slCustom = [];
    _slSave();
    renderShoppingList();
  }
}

function _slCardHtml(it) {
  const icon = _SL_ICONS[it.cat] || '📦';
  const safe = String(it.n).replace(/"/g, '&quot;');
  let meta = '';
  if (it.custom) {
    meta = '<span style="opacity:.85">eigener Eintrag</span>';
  } else if (it.days != null) {
    if (it.days < 0)  meta = '<b>Überfällig</b><br>' + (-it.days) + ' Tage';
    else if (it.days === 0) meta = '<b>Heute</b>';
    else meta = '<b>in ' + it.days + ' T</b>' + (it.qty ? '<br>~ ' + it.qty + ' ' + it.unit : '');
    if (it.qty && it.days != null && it.days >= 0) {
      meta = '<b>~ ' + it.qty + ' ' + it.unit + '</b><br>'
           + (it.days === 0 ? 'heute' : 'in ' + it.days + ' T');
    }
  }
  const cls = (!it.custom && it.days != null && it.days < 0) ? 'sl-card sl-overdue' : 'sl-card';
  return '<div class="' + cls + '" data-name="' + safe + '">'
       + '<span class="sl-icon">' + icon + '</span>'
       + '<span class="sl-name">' + it.n + '</span>'
       + '<span class="sl-meta">' + meta + '</span>'
       + '</div>';
}

function addCustomItem() {
  const inp = document.getElementById('sl-input');
  const name = (inp.value || '').trim();
  if (!name) return;
  if (!_slCustom.includes(name)) _slCustom.push(name);
  _slSave();
  inp.value = '';
  renderShoppingList();
}

function copyShoppingList() {
  const lines = [];
  document.querySelectorAll('#sl-active .sl-card').forEach(c => {
    const name = c.querySelector('.sl-name').textContent;
    const meta = c.querySelector('.sl-meta').textContent.replace(/\s+/g, ' ').trim();
    const qty  = (meta.match(/~\s*[\d,\.]+\s*(Stk|kg)/) || [''])[0];
    lines.push('- ' + (qty ? qty + '  ' : '') + name);
  });
  if (!lines.length) { alert('Liste ist leer.'); return; }
  const text = 'Einkaufszettel' + String.fromCharCode(10) + lines.join(String.fromCharCode(10));
  navigator.clipboard.writeText(text).then(
    () => alert('In Zwischenablage kopiert (' + lines.length + ' Artikel).'),
    () => alert('Kopieren fehlgeschlagen.')
  );
}

// ── Forecast ────────────────────────────────────────────────────────────────
function renderForecast() {
  const wrap = document.getElementById('forecast-wrap');
  if (!wrap) return;
  const f = FORECAST;
  const pct = Math.min(f.days_elapsed / f.days_total * 100, 100).toFixed(0);
  const vsSign = f.vs_avg >= 0 ? '+' : '';
  const vsColor = f.vs_avg > 10 ? '#cc0000' : f.vs_avg < -10 ? '#2a9d8f' : '#555';
  wrap.innerHTML = `
    <div class="stats-grid" style="margin-bottom:1rem">
      <div class="stat"><div class="val" style="font-size:1.3rem">${eur(f.spent)}</div>
        <div class="lbl">Bisher (Tag ${f.days_elapsed}/${f.days_total})</div></div>
      <div class="stat"><div class="val" style="font-size:1.3rem">${eur(f.forecast)}</div>
        <div class="lbl">Hochrechnung Monatsende</div></div>
      <div class="stat"><div class="val" style="font-size:1.3rem">${eur(f.hist_avg)}</div>
        <div class="lbl">Ø letzte 6 Monate</div></div>
      <div class="stat"><div class="val" style="font-size:1.3rem;color:${vsColor}">${vsSign}${f.vs_avg.toFixed(1).replace('.',',')} %</div>
        <div class="lbl">Hochrechnung vs. Ø</div></div>
    </div>
    <div style="background:#f0f2f5;border-radius:8px;padding:.8rem;font-size:.85rem;color:#666">
      <div style="display:flex;justify-content:space-between;margin-bottom:.5rem">
        <span>${f.trips} Einkäufe bisher</span>
        <span>${pct} % des Monats vergangen</span>
      </div>
      <div style="background:#ddd;border-radius:4px;height:8px">
        <div style="background:#cc0000;width:${pct}%;height:8px;border-radius:4px"></div>
      </div>
    </div>`;
}

// ── Preis-Alarm ──────────────────────────────────────────────────────────────
function renderPriceAlarm() {
  const el = document.getElementById('alarm-count');
  if (el) el.textContent = PRICE_ALARM.length + ' Artikel über Durchschnitt';
  const body = document.getElementById('alarm-body');
  if (!body) return;
  body.innerHTML = PRICE_ALARM.map(r => `<tr>
    <td>${r.n}</td>
    <td class="num">${eur(r.avg)}</td>
    <td class="num"><strong>${eur(r.last)}</strong></td>
    <td class="num"><span class="pct-pos">+${r.dev.toFixed(1).replace('.',',')} %</span></td>
    <td class="num">${isoDE(r.date)}</td>
    <td class="num">${r.cnt}</td>
  </tr>`).join('');
  alignHeaders('alarm-table');
}

// ── Saisonale Muster ─────────────────────────────────────────────────────────
function renderSeasonChart() {
  const palette = ['#2a9d8f','#e9c46a','#e63946','#457b9d','#f4a261',
                   '#264653','#52b788','#9b2226','#6d6875','#b5838d',
                   '#e76f51','#0077b6','#a7c957','#c77dff','#4caf50'];
  const seasons = ['Frühling','Sommer','Herbst','Winter'];
  const datasets = SEASONAL_CATS.map((cat, i) => ({
    label: cat,
    data: seasons.map(s => (SEASONAL_DATA[s] || [])[i] || 0),
    backgroundColor: palette[i % palette.length] + 'bb',
    borderColor: palette[i % palette.length],
    borderWidth: 1,
  }));
  new Chart(document.getElementById('seasonChart'), {
    type: 'bar',
    data: { labels: seasons, datasets },
    options: {
      responsive: true, maintainAspectRatio: false,
      plugins: { legend: { position: 'bottom', labels: { boxWidth: 12, font: { size: 10 } } } },
      scales: {
        x: { stacked: true },
        y: { stacked: true, beginAtZero: true, min: 0,
              ticks: { callback: v => '€ ' + v.toLocaleString('de-DE', {maximumFractionDigits:0}) } },
      }
    }
  });
}

// ── Warenkorbanalyse ─────────────────────────────────────────────────────────
let _bSort = { key: 'cnt', dir: -1 };
function _applyBasket() {
  const q = (document.getElementById('basket-search')?.value || '').toLowerCase();
  let data = q
    ? BASKET.filter(r => r.a.toLowerCase().includes(q) || r.b.toLowerCase().includes(q))
    : BASKET.slice();
  const {key, dir} = _bSort;
  data = data.slice().sort((a, b) => {
    let av = a[key], bv = b[key];
    if (typeof av === 'string') { av = av.toLowerCase(); bv = bv.toLowerCase(); }
    return av < bv ? -dir : av > bv ? dir : 0;
  });
  document.getElementById('basket-body').innerHTML = data.map(r =>
    `<tr><td class="num"><strong>${r.cnt}×</strong></td><td>${r.a}</td><td>${r.b}</td></tr>`
  ).join('');
}
function filterBasket() { _applyBasket(); }
function sortBasket(th) {
  const key = th.dataset.key;
  _bSort = _bSort.key === key ? {key, dir: _bSort.dir * -1} : {key, dir: key === 'cnt' ? -1 : 1};
  document.querySelectorAll('#basket-table th').forEach(h => h.classList.remove('sort-asc','sort-desc'));
  th.classList.add(_bSort.dir === 1 ? 'sort-asc' : 'sort-desc');
  _applyBasket();
}

function initExtras() {
  window._extrasInit = true;
  renderSeasonChart();
  _applyBasket();
  alignHeaders('basket-table');
}
</script>
</body>
</html>
